import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './SuperAdminPage.css';

export default function SuperAdminPage({page,companies,setPage,companyForm,setCompanyForm,addCompany,onOpenCompany}) { const [showForm,setShowForm]=useState(false); const active=companies.filter(c=>c.status==='Active').length; return <div className="module-page module-page--super-admin"><div className="page-heading"><div><div className="eyebrow">PLATFORM CONTROL CENTER</div><h1>{page==='Companies'?'Client workspaces':page==='Subscriptions'?'Plans & subscriptions':'Platform overview'}</h1><p>Manage customer companies from one central workspace.</p></div><div className="heading-actions"><button className="btn primary" onClick={()=>{setPage('Companies');setShowForm(true)}}>＋ Add company</button></div></div><div className="stats-grid"><Stat label="Total workspaces" value={companies.length} change="All registered companies" icon="▦" tone="purple" foot="Across all plans"/><Stat label="Active workspaces" value={active} change="Ready to use" icon="✓" tone="green" foot="Workspace status"/><Stat label="Total seats" value={companies.reduce((s,c)=>s+Number(c.users||0),0)} change="Configured user capacity" icon="♙" tone="blue" foot="Seat limits are demo only"/><Stat label="Plans configured" value={new Set(companies.map(c=>c.plan)).size} change="Starter & Growth" icon="◇" tone="orange" foot="Billing not connected"/></div>{page==='Subscriptions'&&<div className="plan-grid">{[['Starter','₹299','1–2 seats','Leads, tasks, basic reports'],['Growth','₹799','Up to 5 seats','Attendance, visits, team reports'],['Business','₹1,499','Up to 15 seats','Advanced insights, permissions']].map(p=><div className="panel plan-card" key={p[0]}><span className="pill">DEMO PLAN</span><h2>{p[0]}</h2><h3>{p[1]}<small>/ month</small></h3><p>{p[2]}</p><div className="plan-rule"/><p>{p[3]}</p><button className="btn secondary" onClick={()=>setPage('Companies')}>Assign from workspace</button></div>)}</div>}{page!=='Subscriptions'&&<section className="panel companies-panel"><div className="panel-head"><div><h3>All client workspaces</h3><p>Each workspace represents a separate company tenant in the future production backend.</p></div><div className="table-count">{companies.length} workspaces</div></div><div className="table-wrap"><table><thead><tr><th>COMPANY</th><th>PLAN</th><th>SEATS</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{companies.map(c=><tr key={c.id}><td><div className="company-table-cell"><div className="company-avatar" style={{background:c.color}}>{c.short}</div><div><b>{c.name}</b><small>{c.id}</small></div></div></td><td><span className="plan-label">{c.plan}</span></td><td>{c.users} seats</td><td><Status value={c.status}/></td><td><button className="btn small secondary" onClick={()=>onOpenCompany(c)}>Open demo ↗</button></td></tr>)}</tbody></table></div></section>}{showForm&&<Modal title="Create client workspace" onClose={()=>setShowForm(false)}><form className="form-grid" onSubmit={e=>{addCompany(e);setShowForm(false)}}><Field label="Company / brand name" required><input required value={companyForm.name} onChange={e=>setCompanyForm({...companyForm,name:e.target.value})} placeholder="e.g. BlueSky Realty"/></Field><Field label="Plan"><select value={companyForm.plan} onChange={e=>setCompanyForm({...companyForm,plan:e.target.value})}>{['Starter','Growth','Business','Enterprise'].map(x=><option>{x}</option>)}</select></Field><Field label="Seat limit"><input type="number" min="1" value={companyForm.users} onChange={e=>setCompanyForm({...companyForm,users:e.target.value})}/></Field><Field label="Brand color"><input type="color" value={companyForm.color} onChange={e=>setCompanyForm({...companyForm,color:e.target.value})}/></Field><div className="notice wide">This creates a demo workspace record in this browser. Production company isolation, authentication, and billing must be enforced by the backend before selling access.</div><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setShowForm(false)}>Cancel</button><button className="btn primary">Create workspace</button></div></form></Modal>}</div>; }
